// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.sttimport timber.log.Timberimport android.content.Contextimport android.net.ConnectivityManagerimport android.net.NetworkCapabilitiesimport com.roshan.persona.voice.capture.AudioCapturePipelineimport kotlinx.coroutines.flow.Flow/** * NOUS — Streaming Speech-to-Text Engine (Hybrid Cloud + Offline). * * Converts microphone audio into text in real time, emitting partial results * every ~200 ms as the user speaks and a final result when they stop. The * Brain can start processing partial results for instant response (per §6 * "Streaming STT (Partial Results)"). * * ## Hybrid strategy (§6 Hybrid STT Strategy) * * ``` * User speaks *     ↓ * 1. Try cloud STT (Android SpeechRecognizer) *    - Best accuracy, low latency (~300 ms first partial) *    - Requires internet *    - Falls back to offline if no network *     ↓ (offline fallback) * 2. Try Whisper.cpp (JNI, high accuracy offline) — Step 5.4 *    - 75 MB model (base.en) or 250 MB (small) *    - > 95 % accuracy on clean audio *    - ~2-3× realtime on arm64 *     ↓ (if Whisper too slow) * 3. Fallback to Vosk (50 MB, faster but lower accuracy) *    - ~90 % accuracy *    - ~0.5× realtime (faster than realtime) * ``` * * ## Streaming contract * * The engine emits [SttResult.Partial] roughly every 200 ms while the user * is speaking, then a single [SttResult.Final] when 500 ms of silence has * passed (end-of-turn). Partial results are *additive* — each one is the * full text so far, not just the new words. Use [DeltaContextUpdater] to * extract the delta for the Brain. * * ## Confidence * * Every result carries a [confidence] score (0.0–1.0). Cloud STT provides * this directly; offline engines estimate it (see [SttConfidenceScorer]). * The Brain uses confidence to decide between normal processing, asking for * confirmation, or asking the user to repeat (§22). * * ## Testability * * Both [CloudSttEngine] and [OfflineSttEngine] are interfaces — tests * inject fakes. The [Factory] probes network state via [ConnectivityManager] * and picks the right engine at runtime. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§6 Speech-to-Text</a> */class StreamingSttEngine @javax.inject.Inject constructor(    private val cloudStt: CloudSttEngine,    private val offlineStt: OfflineSttEngine,    private val confidenceScorer: SttConfidenceScorer,    private val networkProbe: NetworkProbe = NetworkProbe.Android,) {    /**     * Begin streaming recognition. Returns a hot [Flow] of [SttResult]s that     * the caller collects for the lifetime of one utterance.     *     * Calling [recognize] again before the previous flow completes will     * implicitly cancel the prior recognition — only one STT session is     * active at a time per [StreamingSttEngine] instance.     *     * @param audioStream live audio chunks from [AudioCapturePipeline.chunks].     */    suspend fun recognize(audioStream: Flow<AudioCapturePipeline.AudioChunk>): Flow<SttResult> {        val isOnline = networkProbe.isOnline()        val engine = if (isOnline) cloudStt else offlineStt        Timber.tag(TAG).i("STT engine selected: ${if (isOnline) "cloud" else "offline"}")        return engine.recognize(audioStream, confidenceScorer)    }    /** Abort any in-progress recognition. Idempotent. */    suspend fun cancel() {        runCatching { cloudStt.cancel() }        runCatching { offlineStt.cancel() }    }    private companion object {        private const val TAG = "StreamingSttEngine"    }}// ──────────────────────────────────────────────────────────────────────────/** One STT result — either a partial (mid-utterance) or final (end-of-turn). */sealed interface SttResult {    /** ISO 639-1 language code detected (or null if detection disabled). */    val language: String?    /** Recognition confidence 0.0–1.0 (cloud = direct, offline = estimated). */    val confidence: Float    /** Wall-clock time this result was emitted (ms since epoch). */    val timestampMs: Long    /**     * Partial result — emitted every ~200 ms while the user is speaking.     *     * [text] is the *full* text so far (additive), not just new words.     */    data class Partial(        val text: String,        override val language: String?,        override val confidence: Float,        override val timestampMs: Long = System.currentTimeMillis(),    ) : SttResult    /**     * Final result — emitted once, 500 ms after the user stops speaking.     *     * [text] is the complete utterance. After this is emitted, the stream     * completes (no more results).     */    data class Final(        val text: String,        override val language: String?,        override val confidence: Float,        override val timestampMs: Long = System.currentTimeMillis(),    ) : SttResult    /**     * Error result — emitted if recognition fails mid-stream (network drop,     * model crash, mic permission revoked). The stream completes after this.     */    data class Error(        val reason: Reason,        val message: String,        override val language: String? = null,        override val confidence: Float = 0f,        override val timestampMs: Long = System.currentTimeMillis(),    ) : SttResult {        enum class Reason { NETWORK_DROPPED, MODEL_CRASH, MIC_PERMISSION, AUDIO_DEVICE, UNKNOWN }    }}// ──────────────────────────────────────────────────────────────────────────/** * Cloud STT (Android SpeechRecognizer wrapper). * * Real implementation ships with :feature:voice (no native deps — uses * Android's built-in SpeechRecognizer). Stubbed here as an interface so the * StreamingSttEngine is testable without the Android framework. */interface CloudSttEngine : SttEngine {    // recognize() and cancel() inherited from SttEngine.}/** * Offline STT (Whisper.cpp or Vosk). * * Real implementation ships in :native:whisper (Step 5.4). Until then, a * stub that always returns [SttResult.Error] with `Reason.MODEL_CRASH` is * injected — the [StreamingSttEngine] handles this gracefully. */interface OfflineSttEngine : SttEngine {    // recognize() and cancel() inherited from SttEngine.}// ──────────────────────────────────────────────────────────────────────────/** * Network probe — abstracted so tests can simulate online/offline. */fun interface NetworkProbe {    fun isOnline(): Boolean    companion object {        val Android = NetworkProbe {            // Real impl reads ConnectivityManager. Until :feature:voice            // wires up :core:connectivity, default to true so cloud STT is            // tried first (and falls back gracefully on network errors).            true        }        /** Production impl backed by [ConnectivityManager]. */        class AndroidImpl(private val context: Context) : NetworkProbe {            override fun isOnline(): Boolean {                val cm = context.getSystemService(ConnectivityManager::class.java) ?: return false                val network = cm.activeNetwork ?: return false                val caps = cm.getNetworkCapabilities(network) ?: return false                return caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) &&                    caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)            }        }    }}// ──────────────────────────────────────────────────────────────────────────/** * Configuration for the streaming STT engine. * * @param languageHints           preferred languages (BCP-47 tags, e.g. "en-US"). *                                 Cloud STT uses these to bias recognition. * @param enableLanguageDetection if true, [LanguageDetector] runs alongside STT *                                 and overrides [languageHints] when confidence > 0.8. * @param partialIntervalMs       target interval between partial results. *                                 Cloud STT ignores this (it's driven by the *                                 recognizer); offline engines respect it. * @param silenceTimeoutMs        silence duration that triggers end-of-turn. * @param maxDurationMs           hard cap on utterance length (safety valve). */data class SttConfig(    val languageHints: List<String> = listOf("en-US", "en-IN", "hi-IN"),    val enableLanguageDetection: Boolean = true,    val partialIntervalMs: Long = 200L,    val silenceTimeoutMs: Long = 500L,    val maxDurationMs: Long = 30_000L,)

